// Imports left for future use
import { formatDatetime } from "@/common/utils/formatting/datetime";
import type { IAdapterSpec } from "@/features/adapters/types/IAdapterSpec";
import type { IValheimServerStateInfo } from "@/features/adapters/valheim/types/IValheimServerStateInfo";
import type { IPlayer } from "@/features/player-log/types/IPlayer";
import type { IPlayerLog } from "@/features/player-log/types/IPlayerLog";
import type { IPlayerLogEntry } from "@/features/player-log/types/IPlayerLogEntry";
import type { IPlayerLogEvent } from "@/features/player-log/types/IPlayerLogEvent";

const VALHEIM_RE = {
  serverStarted:
    /Session "([^"]+)" with join code (\d+) and IP ([\d.]+):(\d+) is active with (\d+) player\(s\)/i,
  // FIXME
  gameVersion: /_______________/i,
  // FIXME
  serverSaved: /_______________/i,
  // FIXME
  playerJoined: /_______________/i,
  // FIXME
  playerLeft: /_______________/i,
  // FIXME
  includesUserInfo: /_______________/i,
  // TODO Add more
};

export const VALHEIM_ADAPTER_SPEC: IAdapterSpec<
  "valheim",
  IValheimServerStateInfo
> = {
  id: "valheim",
  name: "Valheim",
  logo: {
    src: "data:image/png;base64,",
    height: 300,
    width: 462,
    omitTextFromLogoBanner: true,
  },
  configSpecs: {},
  stateInfoSpec: {
    categorizeLogLine: (line) => {
      if (VALHEIM_RE.serverSaved.test(line)) return "save";
      if (
        VALHEIM_RE.playerJoined.test(line) ||
        VALHEIM_RE.playerLeft.test(line) ||
        VALHEIM_RE.includesUserInfo.test(line)
      )
        return "player";
      if (/error/i.test(line)) return "error";
      return undefined;
    },
    checkStarted: (data, _current) => VALHEIM_RE.serverStarted.test(data),
    infoGetters: [
      (data, _current) => ({
        name: data.match(VALHEIM_RE.serverStarted)?.[1],
        joinCode: data.match(VALHEIM_RE.serverStarted)?.[2],
        ip: data.match(VALHEIM_RE.serverStarted)?.[3],
        port: data.match(VALHEIM_RE.serverStarted)?.[4],
      }),
    ],
  },
};
